(function(root){'use strict';
const R=6371000,toRad=x=>x*Math.PI/180;
function distance(a,b){const p=toRad(b.lat-a.lat),l=toRad(b.lon-a.lon),v=Math.sin(p/2)**2+Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(l/2)**2;return R*2*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)));}
function boundsOverlap(bounds,point,radius){if(!bounds||![point.lat,point.lon,radius,...bounds].every(Number.isFinite))return true;const dy=radius/111000,dx=radius/(111000*Math.max(.1,Math.cos(toRad(point.lat))));return bounds[0]<=point.lon+dx&&bounds[2]>=point.lon-dx&&bounds[1]<=point.lat+dy&&bounds[3]>=point.lat-dy;}
function qCoordinate(text){const m=String(text).trim().match(/^(\d{2})(\d{2})([NS])(\d{3})(\d{2})([EW])$/);if(!m||+m[2]>=60||+m[5]>=60)return null;const lat=(+m[1]+m[2]/60)*(m[3]==='S'?-1:1),lon=(+m[4]+m[5]/60)*(m[6]==='W'?-1:1);return Math.abs(lat)<=90&&Math.abs(lon)<=180?{lat,lon}:null;}
function notamTime(raw){const m=String(raw).match(/^(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})/);if(!m)return null;const v=Date.UTC(2000+Number(m[1]),Number(m[2])-1,Number(m[3]),Number(m[4]),Number(m[5]));const d=new Date(v);return d.getUTCMonth()===Number(m[2])-1&&d.getUTCDate()===Number(m[3])&&Number(m[4])<24&&Number(m[5])<60?v:null;}
function londonStart(date,hour){const target=Date.parse(date+'T'+hour+':00:00Z');if(!Number.isFinite(target))return null;const formatter=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const candidates=[];for(const offset of [0,3600000]){const v=target-offset,p=Object.fromEntries(formatter.formatToParts(new Date(v)).map(p=>[p.type,p.value]));if(p.year+'-'+p.month+'-'+p.day===date&&p.hour===hour&&p.minute==='00')candidates.push(v);}return candidates.length===1?candidates[0]:null;}
function overseasAdvisory(r){const body=String(r.body||'').replace(/\s+/g,' ').toUpperCase();if(!/SECURITY\s*-\s*HAZARDOUS SITUATION/.test(body)||!/(?:UK|UNITED KINGDOM) REGISTERED AIR OPERATORS/.test(body)||!body.includes('FIR'))return null;const codes=Array.from(body.matchAll(/\(([A-Z]{4})\)/g),m=>m[1]);if(!codes.length||codes.some(c=>c.startsWith('EG')))return null;return 'Overseas conflict-zone advisory referencing '+codes.join(', ')+'; not a local UK flight-area restriction. Review if your operation extends there.';}
function lowerLimit(text){const t=String(text||'').trim().toUpperCase().replace(/\s+/g,' ');if(t==='SFC'||t==='GND')return{metres:0,datum:'AGL'};const m=t.match(/^(\d+(?:\.\d+)?)\s*(FT|M)\s*(AGL|AMSL|MSL)$/);return m?{metres:Number(m[1])*(m[2]==='FT'?.3048:1),datum:m[3]==='AGL'?'AGL':'AMSL'}:null;}
function altitudeExclusion(r,{maxHeight,maxTerrain=null}){if(/\bGNSS\b|\bGPS\b|JAMM|SPOOF|LASER|EMERGENCY/i.test(r.body||''))return null;const low=lowerLimit(r.lower);if(!low||!Number.isFinite(maxHeight)||maxHeight<=0)return null;const ceiling=low.datum==='AGL'?maxHeight:Number.isFinite(maxTerrain)?maxTerrain+maxHeight:null;if(ceiling!==null&&low.metres>ceiling+150)return 'Lower limit '+r.lower+' is above the stated flight ceiling plus a 150 m screening buffer'+(low.datum==='AMSL'?' (using the pilot-supplied highest terrain elevation).':'.');return null;}
function screenNotams(records,{point,radius,start,end,maxHeight=null,maxTerrain=null}){const nearby=[],unlocated=[],excluded=[],filtered=[];for(const r of records){const from=notamTime(r.start),to=/^PERM$/.test(r.end)?Infinity:notamTime(r.end);if(from!==null&&from>end||to!==null&&to<start){excluded.push(r);continue;}const overseas=overseasAdvisory(r);if(overseas){filtered.push({...r,filterReason:overseas});continue;}const centre=qCoordinate(r.coordinate),nm=Number(r.radius),spatial=centre&&String(r.radius).trim()!==''&&Number.isFinite(nm)&&nm>=0;
if(!spatial){unlocated.push({...r,reason:'Location/radius unparsed: review manually'});continue;}if(distance(point,centre)>radius+nm*1852+500){excluded.push(r);continue;}const altitude=r.type==='C'?null:altitudeExclusion(r,{maxHeight,maxTerrain});if(altitude){filtered.push({...r,filterReason:altitude});continue;}nearby.push({...r,centre,screenRadius:nm*1852,timeUncertain:from===null||to===null,altitudeUncertain:lowerLimit(r.lower)===null});}return{nearby,unlocated,excluded,filtered};}
function collectionHealth({feed,request={},start,end,now=Date.now()}){if(request.state==='pending')return{code:'pending',usable:false,message:(request.manual?'Refresh requested':'Automatic NOTAM request started')+' — request is being processed. Any retained list is not validated for this request.'};if(request.state==='failed')return{code:'failed',usable:false,message:'NOTAM request FAILED. '+(feed?'The retained list is stale/unverified after this failed refresh.':'No current list is available.')+' Obtain a current NOTAM briefing yourself using the official NATS links below.'};if(!feed)return{code:'missing',usable:false,message:'No NOTAM collection loaded. Press Refresh airspace & NOTAMs, or obtain an official briefing using the links below.'};const stale=!freshIssued(feed.issued,now),windowMissing=!Number.isFinite(start)||!Number.isFinite(end)||!Number.isFinite(Date.parse(feed.validFrom))||!Number.isFinite(Date.parse(feed.validTo))||start<Date.parse(feed.validFrom)||end>Date.parse(feed.validTo);if(stale||windowMissing){const reason=stale?'The collection is stale.':'The collection does not cover the full ±2-hour search window.';return{code:stale?'stale':'coverage',usable:false,message:reason+(request.lastManualAt&&request.state==='succeeded'?' Your Refresh request completed and the response was processed, but the supplier still returned incomplete/out-of-date coverage. Obtain the required briefing yourself using the official NATS links below.':' Press Refresh airspace & NOTAMs. If coverage remains incomplete, obtain the required briefing yourself using the official NATS links below.')};}return{code:'current',usable:true,message:'NOTAM response received and processed; issue time and search-window coverage checked.'};}
function freshIssued(issued,now=Date.now()){const t=Date.parse(issued);return Number.isFinite(t)&&t<=now+300000&&now-t<=2*3600000;}
const api={distance,boundsOverlap,qCoordinate,notamTime,londonStart,screenNotams,freshIssued,overseasAdvisory,lowerLimit,altitudeExclusion,collectionHealth};root.FLIGHT_AIRSPACE=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
